addQ("pjo-k2-u17", 2, "Ciri-Ciri Air Bersih untuk Kebutuhan Minum dan Mandi", "sulit", "Berdasarkan standar kesehatan lingkungan, air bersih yang sehat harus memenuhi syarat fisik yaitu ...", ["Tidak berwarna (jernih), tidak berbau busuk, dan tidak berasa asing", "Berwarna kecokelatan kental", "Beraroma minyak tanah menyengat", "Berasa asin pahit"], 0, "Air bersih higienis harus jernih tanpa kekeruhan, tidak berbau, dan tidak berasa kimiawi.");
addQ("pjo-k2-u18", 2, "Pengelolaan Sampah Organik dan Anorganik di Sekolah", "sulit", "Di sekolah disediakan tempat sampah warna hijau untuk sampah daun/sisa makanan (organik) dan tempat sampah kuning untuk botol plastik/kaleng (anorganik). Pemilahan ini bertujuan untuk ...", ["Memudahkan pengolahan sampah organik menjadi kompos dan daur ulang plastik", "Menghabiskan anggaran sekolah membeli tong", "Membuat murid bingung", "Membuat tumpukan sampah semakin tinggi"], 0, "Pemilahan sampah dari sumber memfasilitasi komposting ramah lingkungan dan sirkular ekonomi.");
addQ("pjo-k2-u19", 2, "Bahaya Menghirup Asap Rokok Bagi Perokok Pasif", "sulit", "Anak yang sering menghirup asap rokok dari orang dewasa di sekitarnya (perokok pasif) berisiko tinggi menderita gangguan pernapasan berupa ...", ["Asma kambuh, batuk bronkitis kronis, dan penurunan fungsi paru-paru", "Ketajaman pendengaran bertambah", "Pertumbuhan tinggi badan berlebih", "Kekuatan otot melipat ganda"], 0, "Asap rokok sampingan mengandung racun nikotin dan tar karsinogenik yang merusak alveolus paru anak.");
addQ("pjo-k2-u20", 2, "Manfaat Menjaga Kerapian Loker Sepatu Sekolah", "sulit", "Menaruh sepatu olahraga di loker rak sepatu sekolah dalam keadaan bersih dan kering setelah dipakai bertujuan untuk ...", ["Mencegah bau kaki tidak sedap akibat bakteri keringat dan menjaga kerapian koridor kelas", "Menyembunyikan sepatu dari teman", "Membuat sepatu cepat rusak", "Agar sepatu tidak bisa dipakai lagi"], 0, "Sirkulasi udara di rak sepatu mencegah proliferasi bakteri brevibacterium penyebab bau kaki.");
addQ("pjo-k2-u21", 2, "Latihan Naik Turun Bangku (Step-Up)", "sulit", "Latihan melangkah naik dan turun bangku kecil berulang-ulang dengan tempo ritmis berguna untuk melatih ...", ["Daya tahan kardiorespirasi (jantung paru) dan kekuatan otot paha/betis", "Kelenturan jari telunjuk", "Kekuatan gigi depan", "Ketebalan rambut"], 0, "Step-up test adalah metode aerobik mengukur efisiensi kerja jantung dan kekuatan kuadrisep.");
addQ("pjo-k2-u22", 2, "Sikap Menolak Bujukan Orang Asing Tak Dikenal", "sulit", "Saat pulang sekolah menunggu jemputan, jika ada orang asing tak dikenal menawarkan permen dan mengajak naik sepeda motornya, tindakan aman yang harus dilakukan anak adalah ...", ["Menolak dengan tegas, berteriak meminta tolong, dan segera lari masuk kembali ke pos satpam sekolah", "Menerima permen dan ikut naik motornya", "Mengikuti orang asing ke tempat sepi", "Memberikan alamat rumah lengkap"], 0, "Edukasi stranger danger mencegah risiko penculikan dan kekerasan pada anak.");
addQ("pjo-k2-u23", 2, "Mengenal Sentuhan Boleh dan Sentuhan Tidak Boleh", "sulit", "Bagian tubuh pribadi anak yang TIDAK BOLEH disentuh atau dilihat oleh orang lain (kecuali dokter saat diperiksa didampingi orang tua) meliputi ...", ["Dada, organ genital/antara paha, dan pantat", "Tangan dan kaki", "Rambut dan pundak", "Punggung sepatu"], 0, "Pendidikan perlindungan diri mengenalkan proteksi area privat tubuh dari pelecehan.");
addQ("pjo-k2-u24", 2, "Pentingnya Mengunci Pintu Toilet Saat Digunakan", "sulit", "Saat buang air di toilet umum atau sekolah, kita harus mengunci pintu dari dalam untuk ...", ["Menjaga privasi kehormatan diri dan mencegah orang lain masuk tiba-tiba", "Bermain air di dalam sendirian", "Mengurung diri seharian", "Menakut-nakuti teman di luar"], 0, "Privasi dan rasa aman adalah hak asasi setiap individu di fasilitas sanitasi.");
addQ("pjo-k2-u25", 2, "Manfaat Jalan Santai Pagi Hari", "sulit", "Berjalan santai menghirup udara segar pagi hari sambil terkena sinar matahari pagi bermanfaat bagi tubuh untuk ...", ["Sintesis vitamin D alami untuk kepadatan tulang dan menyegarkan pikiran", "Membuat kulit terbakar hitam", "Menghabiskan tenaga belajar", "Menurunkan kekebalan tubuh"], 0, "Sinar matahari pagi mengubah provitamin D pada kulit menjadi kalsiferol aktif penguat tulang.");
addQ("pjo-k2-u26", 2, "Latihan Meliuk dan Meregang Otot Dada", "sulit", "Kedua tangan direntangkan ke belakang dan dada dibusungkan ke depan secara perlahan sambil menarik napas dalam bermanfaat untuk ...", ["Memperluas kapasitas sangkar dada dan meregangkan otot pektoralis", "Mematahkan tulang rusuk", "Membuat kepala pusing", "Mengecilkan paru-paru"], 0, "Peregangan dada melenturkan dinding thoraks dan mempermudah ekspansi paru.");
addQ("pjo-k2-u27", 2, "Penyebab Sakit Diare Akibat Makanan Tercemar", "sulit", "Gejala buang air besar cair berkali-kali disertai mulas melilit pada penyakit diare disebabkan oleh ...", ["Infeksi bakteri atau parasit pada saluran usus akibat mengonsumsi makanan/minuman yang tercemar", "Kurang tidur malam", "Membaca buku terlalu lama", "Memakai baju terbalik"], 0, "Enteropatogen melepaskan enterotoksin yang mengganggu penyerapan air di mukosa kolon usus.");
addQ("pjo-k2-u28", 2, "Tindakan Mengatasi Tubuh Kurang Cairan Akibat Diare", "sulit", "Pertolongan pertama pada anak yang diare untuk mencegah dehidrasi parah yang mengancam jiwa adalah segera meminum ...", ["Cairan oralit (larutan gula garam) atau air kelapa muda", "Minyak goreng mentah", "Susu kental manis pekat", "Air cuka asam"], 0, "Oralit mengembalikan keseimbangan elektrolit natrium, kalium, dan cairan tubuh.");
addQ("pjo-k2-u29", 2, "Adab Menggunakan Lapangan Olahraga Bersama", "sulit", "Setelah selesai jam pelajaran olahraga, peralatan bola kasti dan pemukul kayu harus ...", ["Dikumpulkan dan dihitung kembali lalu disimpan rapi di gudang olahraga", "Dibiarkan berserakan di rumput lapangan", "Dilemparkan ke selokan", "Dibawa pulang ke rumah siswa"], 0, "Merawat dan mengembalikan sarana olahraga sekolah adalah tanggung jawab bersama.");
addQ("pjo-k2-u30", 2, "Kebugaran Fisik Melalui Pola Hidup Bersih dan Sehat (PHBS)", "sulit", "Penerapan Pola Hidup Bersih dan Sehat (PHBS) di sekolah meliputi kebiasaan ...", ["Mencuci tangan dengan air sabun, membuang sampah pada tempatnya, dan memilih jajanan sehat", "Makan makanan kotor yang jatuh di tanah", "Mencoret-coret meja kelas", "Tidak pernah berolahraga"], 0, "PHBS menanamkan budaya hidup higienis dan pencegahan preventif penyakit di sekolah.");

