addQ("pjo-k3-m01", 3, "Permainan Tradisional Gobak Sodor", "mudah", "Permainan tradisional berkelompok di mana satu regu menjaga garis kotak lapangan dan regu lain berusaha melintas menembus barisan tanpa tersentuh adalah ...", ["Gobak Sodor (Hadang)", "Sepak bola", "Bulu tangkis", "Tenis meja"], 0, "Gobak sodor melatih kelincahan dan koordinasi strategi tim menghadang lawan.");
addQ("pjo-k3-m02", 3, "Permainan Tradisional Bentengan", "mudah", "Permainan tradisional merebut markas tiang/pohon milik kelompok lawan dengan cara menyentuh benteng lawan disebut permainan ...", ["Bentengan", "Engklek", "Congklak", "Bekel"], 0, "Bentengan menguji kecepatan lari, strategi menyergap, dan menjaga benteng.");
addQ("pjo-k3-m03", 3, "Permainan Bola Kasti Bola Kecil", "mudah", "Permainan kasti tergolong ke dalam jenis permainan olahraga bola ...", ["Kecil", "Besar", "Keranjang", "Gawang"], 0, "Kasti menggunakan bola karet tenis kecil dan tongkat pemukul.");
addQ("pjo-k3-m04", 3, "Tongkat Pemukul Kasti", "mudah", "Alat yang digunakan untuk memukul bola dalam permainan kasti terbuat dari bahan ...", ["Kayu yang kokoh", "Besi cor tebal", "Plastik tipis mudah pecah", "Kaca beling"], 0, "Kayu pemukul kasti dibuat dengan pegangan nyaman dan bilah kayu padat.");
addQ("pjo-k3-m05", 3, "Senam Ketangkasan Matras", "mudah", "Gerakan berguling ke depan (forward roll) dalam senam ketangkasan wajib dilakukan di atas ...", ["Matras senam", "Lantai semen keras", "Paving blok", "Aspal jalan"], 0, "Matras busa melindungi tulang tengkuk leher dan punggung saat berguling.");
addQ("pjo-k3-m06", 3, "Bagian Tubuh Mendarat Guling Depan", "mudah", "Saat melakukan guling ke depan di atas matras, bagian tubuh belakang yang pertama kali menyentuh matras setelah tangan adalah ...", ["Tengkuk leher bagian belakang", "Dahi jidat", "Hidung", "Dagu"], 0, "Dagu ditarik ke dada sehingga tengkuk yang menyentuh matras pertama kali.");
addQ("pjo-k3-m07", 3, "Renang Gaya Dada Posisi Tubuh", "mudah", "Pada renang gaya dada, posisi dada dan perut menghadap ke arah ...", ["Permukaan air (dasar kolam)", "Langit ke atas", "Samping kiri", "Tegak lurus berdiri"], 0, "Gaya dada dilakukan dengan dada menghadap ke permukaan air.");
addQ("pjo-k3-m08", 3, "Istirahat Tidur Pemulihan Tenaga", "mudah", "Bentuk istirahat yang paling baik dan sempurna untuk memulihkan kelelahan fisik dan mental manusia adalah ...", ["Tidur malam yang nyenyak", "Bermain game sepanjang malam", "Menonton TV sampai subuh", "Berlari mengelilingi lapangan"], 0, "Tidur nyenyak meregenerasi sel-sel tubuh dan menyegarkan fungsi otak.");
addQ("pjo-k3-m09", 3, "Bahaya Zat Nikotin Rokok", "mudah", "Zat berbahaya di dalam rokok yang bersifat adiktif (membuat perokok menjadi kecanduan ketagihan) adalah ...", ["Nikotin", "Vitamin C", "Glukosa", "Kalsium"], 0, "Nikotin merangsang ketergantungan dopamin di otak pemicu adiksi.");
addQ("pjo-k3-m10", 3, "Bahaya Minuman Keras Beralkohol", "mudah", "Mengonsumsi minuman keras beralkohol sangat berbahaya bagi tubuh karena dapat merusak organ ...", ["Hati (liver), otak, dan ginjal", "Rambut", "Kuku", "Sepatu"], 0, "Alkohol menyebabkan sirosis kerusakan hati dan penurunan fungsi kognitif otak.");

addQ("pjo-k3-s01", 3, "Kombinasi Gerak Melompat dan Melempar Kasti", "sedang", "Dalam permainan kasti, seorang penjaga yang melompat menangkap bola melambung lalu langsung melemparnya ke base pemukul melakukan kombinasi gerak ...", ["Lokomotor dan manipulatif", "Hanya non-lokomotor", "Hanya pasif", "Refleks tanpa alat"], 0, "Melompat (lokomotor) dipadukan dengan melempar bola kasti (manipulatif).");
addQ("pjo-k3-s02", 3, "Teknik Memukul Bola Kasti Melambung", "sedang", "Agar bola kasti yang dipukul meluncur melambung jauh ke area belakang lapangan, ayunan kayu pemukul diarahkan dari ...", ["Bawah samping menyerong ke atas depan", "Atas dipukulkan ke bawah tanah", "Lurus mendatar saja", "Depan dada ditahan"], 0, "Sudut ayunan dari bawah ke atas melontarkan bola parabola melambung tinggi.");
addQ("pjo-k3-s03", 3, "Teknik Memukul Bola Kasti Mendatar", "sedang", "Pukulan bola kasti mendatar yang menyulitkan regu penjaga menangkap bola dilakukan dengan mengayunkan tongkat pemukul secara ...", ["Lurus sejajar dada mendatar ke depan", "Dari atas ke tanah", "Dari bawah ke atas langit", "Melingkar di belakang punggung"], 0, "Pukulan mendatar menghasilkan laju bola lurus horizontal cepat.");
addQ("pjo-k3-s04", 3, "Taktik Menghindar dalam Gobak Sodor", "sedang", "Pemain penyerang dalam gobak sodor harus memiliki kelincahan (agility) tinggi yang berguna untuk ...", ["Mengubah arah gerak secara cepat guna mengecoh hadangan penjaga garis", "Menabrak penjaga hingga jatuh", "Berhenti diam di sudut kotak", "Menarik baju lawan"], 0, "Kelincahan gerak mengecoh lawan tanpa melanggar garis batas.");
addQ("pjo-k3-s05", 3, "Teknik Awalan Guling Depan", "sedang", "Sikap awal saat hendak melakukan gerakan guling depan dari posisi jongkok di matras adalah ...", ["Kedua telapak tangan menempel di matras selebar bahu dan dagu ditekuk rapat ke dada", "Kepala mendongak ke atas melihat langit", "Kedua kaki diluruskan kaku", "Tidur telungkup"], 0, "Menempelkan dagu ke dada membulatkan punggung agar gulingan mulus.");
addQ("pjo-k3-s06", 3, "Gerakan Mengapung Menginjak Air (Water Trappen)", "sedang", "Gerakan menggerakkan kedua kaki mengayuh melingkar di air dengan kedua tangan mendorong air secara tenang untuk mempertahankan kepala tetap di atas air disebut ...", ["Water trappen (menginjak air)", "Meluncur kencang", "Menyelam dalam", "Loncat indah"], 0, "Water trappen adalah teknik survival mengapung vertikal di air dalam.");
addQ("pjo-k3-s07", 3, "Gerakan Pengambilan Napas Renang Gaya Dada", "sedang", "Pada renang gaya dada, kepala terangkat ke atas permukaan air untuk menghirup oksigen saat gerakan ...", ["Kedua tangan mendayung menekan air ke bawah dan ke dalam dada", "Kaki menendang ke belakang", "Badan meluncur diam", "Kedua kaki ditarik ke depan"], 0, "Dorongan tangan ke bawah mengangkat bahu dan kepala keluar dari air untuk bernapas.");
addQ("pjo-k3-s08", 3, "Dampak Kurang Tidur Terhadap Kekebalan Tubuh", "sedang", "Siswa yang sering begadang dan tidur larut malam akan mudah tertular penyakit flu karena ...", ["Produksi antibodi dan sel darah putih menurun saat kurang istirahat", "Tubuh kelebihan oksigen", "Suhu badan mendingin es", "Tulang memanjang cepat"], 0, "Sistem imun tubuh melepaskan sitokin pelindung infeksi selama fase tidur dalam.");
addQ("pjo-k3-s09", 3, "Bahaya Gas Karbon Monoksida Rokok", "sedang", "Asap rokok mengandung gas karbon monoksida yang berbahaya karena gas ini ...", ["Mengikat sel darah merah sehingga mengurangi pasokan oksigen ke seluruh tubuh", "Menambah energi otot", "Menyegarkan paru-paru", "Membunuh nyamuk"], 0, "Gas CO berikatan kuat dengan hemoglobin, mengurangi kapasitas angkut O2.");
addQ("pjo-k3-s10", 3, "Penyakit Akibat Kecanduan Minuman Keras", "sedang", "Konsumsi alkohol jangka panjang dapat menyebabkan penyakit pengerasan organ hati yang dinamakan ...", ["Sirosis hati", "Radang usus buntu", "Penyakit flu", "Kram betis"], 0, "Sirosis hati adalah kerusakan jaringan parut permanen organ hepar akibat racun alkohol.");
addQ("pjo-k3-s11", 3, "Gerak Dasar Melompat Tali Kebugaran", "sedang", "Latihan melompat tali berputar secara teratur selama 10 menit meningkatkan kebugaran jasmani dalam hal ...", ["Daya tahan sistem kardiovaskular (jantung dan paru-paru)", "Kekuatan indera perasa lidah", "Ketebalan tulang tengkorak", "Pertumbuhan kuku"], 0, "Lompat tali adalah latihan aerobik efektif memacu efisiensi denyut jantung.");
addQ("pjo-k3-s12", 3, "Tugas Regu Penjaga dalam Permainan Kasti", "sedang", "Tugas utama regu penjaga dalam permainan kasti agar dapat bertukar menjadi regu pemukul adalah ...", ["Menangkap bola pukulan lawan secara langsung atau melempar bola mengenai badan pelari lawan", "Menyembunyikan bola kasti di luar lapangan", "Menjatuhkan pemukul kayu", "Menghalangi wasit"], 0, "Menangkap bola lambung langsung (tangkap bola) atau mematikan pelari menghasilkan pergantian bebas.");
addQ("pjo-k3-s13", 3, "Teknik Melempar Bola Menyusur Tanah Kasti", "sedang", "Lemparan bola menyusur tanah (ground ball) digunakan oleh regu penjaga kasti untuk ...", ["Mematikan pelari lawan yang sedang berlari merendah menuju tiang hinggap", "Melambungkan bola ke awan", "Memberikan bola ke penonton", "Memukul tiang bendera"], 0, "Lemparan mendatar rendah menyusur tanah cepat mengenai kaki pelari lawan.");
addQ("pjo-k3-s14", 3, "Sikap Akhir Guling Depan", "sedang", "Setelah badan selesai berguling melingkar di atas matras, sikap akhir guling depan yang sempurna adalah ...", ["Jongkok seimbang dengan kedua tangan lurus ke depan lalu berdiri tegak", "Tidur telungkup di lantai", "Terguling jatuh ke luar matras", "Kepala membentur lantai"], 0, "Mendarat jongkok terkontrol menjaga keseimbangan sebelum berdiri sempurna.");
addQ("pjo-k3-s15", 3, "Senam Ketangkasan Guling Lenting", "sedang", "Gerakan melentingkan tubuh ke atas depan setelah gerakan berguling di atas matras dinamakan ...", ["Guling lenting (neck spring)", "Kayang", "Sikap lilin", "Split"], 0, "Guling lenting memadukan guling tengkuk dengan lecutan kedua tungkai kaki ke depan.");
addQ("pjo-k3-s16", 3, "Etika dan Tata Tertib di Kolam Renang Umum", "sedang", "Sebelum masuk menceburkan diri ke dalam kolam renang umum, pengunjung wajib membilas tubuh di kamar mandi pancuran untuk ...", ["Membersihkan keringat dan kotoran badan agar air kolam renang tetap higienis", "Menghabiskan sabun", "Membuat air kolam keruh", "Mendinginkan baju"], 0, "Membilas badan menjaga sanitasi air kolam renang dari keringat dan kosmetik.");
addQ("pjo-k3-s17", 3, "Manfaat Mengisi Waktu Luang dengan Kegiatan Positif", "sedang", "Kegiatan bermanfaat untuk mengisi waktu libur sekolah yang mendukung kesehatan fisik dan mental adalah ...", ["Bersepeda santai bersama keluarga, berkebun, dan membaca buku pengetahuan", "Bermain game online 12 jam non-stop di kamar tertutup", "Tidur seharian tanpa makan", "Menonton televisi larut malam"], 0, "Aktivitas fisik rekreatif menyegarkan fungsi neuromuskular dan emosi anak.");
addQ("pjo-k3-s18", 3, "Penyakit Batuk Kronis Akibat Paparan Asap Rokok", "sedang", "Anak yang tinggal serumah dengan perokok aktif sering mengalami batuk berdahak lama karena saluran pernapasannya mengalami ...", ["Iritasi dan peradangan (bronkitis)", "Penyembuhan otomatis", "Kekurangan asupan zat kapur", "Kelebihan sel darah merah"], 0, "Bahan iritan asap rokok merangsang hipersekresi mukus dahak saluran napas.");
addQ("pjo-k3-s19", 3, "Menghindari Minuman Beralkohol", "sedang", "Jika ada seseorang yang mengajak atau membujuk kita untuk mencoba meminum minuman keras beralkohol, sikap tegas yang harus diambil adalah ...", ["Menolak dengan tegas dan segera melaporkan kepada orang tua atau guru", "Mencicipi sedikit karena rasa penasaran", "Menerima tawaran agar dianggap keren", "Menyimpannya di dalam tas sekolah"], 0, "Menolak ajakan NAPZA sejak dini melindungi keselamatan masa depan.");
addQ("pjo-k3-s20", 3, "Sportivitas Menerima Kekalahan Permainan", "sedang", "Ketika regu kita kalah dalam pertandingan kasti antar-kelas, sikap yang mencerminkan jiwa kesatria olahraga adalah ...", ["Menyalami regu pemenang dengan tulus dan berlatih lebih kompak untuk lomba berikutnya", "Mengejek pemain lawan", "Merusak peralatan bola dan tongkat kasti", "Menuduh wasit berlaku curang tanpa bukti"], 0, "Menghargai kemenangan lawan membuktikan integritas kepribadian luhur.");

addQ("pjo-k3-u01", 3, "Analisis Kesalahan Fatal Guling Depan", "sulit", "Kesalahan berbahaya saat melakukan guling depan yang dapat mengakibatkan cedera leher adalah ...", ["Menumpu dengan puncak kepala (ubun-ubun) bukannya menekuk dagu ke dada", "Menekuk kedua lutut rapat", "Menggunakan matras busa empuk", "Melipat kedua tangan"], 0, "Menumpu dengan ubun-ubun menekan vertebra servikalis leher dan berisiko fraktur leher.");
addQ("pjo-k3-u02", 3, "Biomekanika Gerak Menolak pada Lompat Kangkang", "sulit", "Saat melakukan lompatan melewati teman yang membungkuk, tolakan kedua telapak tangan pada punggung teman harus kuat dan kedua kaki dibuka lebar ke samping (kangkang) agar ...", ["Tubuh dapat terangkat melayang tinggi tanpa menyenggol atau menabrak punggung teman", "Teman yang membungkuk terjatuh ke tanah", "Kaki mendarat di atas kepala teman", "Punggung teman patah"], 0, "Dorongan tangan vertikal dan abduksi kaki memberi ruang lintasan melayang aman.");
addQ("pjo-k3-u03", 3, "Analisis Fase Gerak Kayuhan Kaki Renang Gaya Dada", "sulit", "Urutan tahapan kayuhan kaki renang gaya dada yang menghasilkan gaya dorong (propulsi) terbesar ke depan adalah ...", ["Menarik kedua kaki ke arah pinggul -> membuka dan memutar telapak kaki ke luar -> menendang kuat melingkar lalu merapatkan kedua kaki lurus", "Mengayuh kaki bergantian seperti mengayuh sepeda", "Kaki diam tanpa bergerak sama sekali", "Menghentakkan kedua lutut lurus ke bawah dasar kolam"], 0, "Tendangan melingkar (whipping kick) diakhiri dorongan luncuran rapat menghasilkan dorongan hidrodinamis.");
addQ("pjo-k3-u04", 3, "Analisis Hambatan Air pada Posisi Streamlining", "sulit", "Mengapa perenang harus menjaga posisi tubuh sedatar mungkin sejajar dengan permukaan air (streamlined position)?", ["Untuk memperkecil luas penampang tubuh sehingga hambatan gesek air (drag) menjadi sekecil mungkin", "Agar perenang tidak terlihat oleh wasit", "Supaya air kolam tidak beriak", "Untuk menambah berat badan di dalam air"], 0, "Bentuk hidrodinamis meminimalisasi hambatan frontal dan turbulensi air.");
